/* Meridian Quest content pack — quests, Spanish. Mirror every change in quests.en.js. */
const FQES={npc:"fred",title:"🐾 Misión personal secreta: Los archivos de Frederick",start:"a",nodes:{
 a:{say:"Frederick deja una carpeta mordisqueada a tus pies. Adentro: recordatorios del veterinario en servilletas, un horario de comida que vive en la cabeza de tres personas, y 40 fotos majestuosas sin publicar. Este perro necesita un sistema.",
    codex:"Las operaciones personales son disciplina de PM con menos riesgo: una sola fuente de verdad, recordatorios recurrentes para todo lo cíclico (comida, veterinario, peluquería), y una lista compartida. Si se repite, lleva recordatorio — la memoria no es un sistema.",
    q:"¿Cómo organizas la vida de Frederick?",
    ch:[{t:"Una nota gigante pegada al refrigerador",out:{r:"mid",concept:"Fuente única de verdad",why:"SÍ es una sola fuente — pero nada le recuerda nada a nadie, y la cita del veterinario muere el día que alguien necesita el refrigerador. Medio crédito.",beat:"Frederick olfatea la nota. No le impresiona."}},
        {t:"Un calendario compartido con recordatorios recurrentes + una lista común",next:"b"},
        {t:"Contratar un asistente para el perro",out:{r:"bad",concept:"Fuente única de verdad",why:"Un asistente para la agenda de un perro es una línea de nómina para un problema que resuelven dos recordatorios recurrentes.",beat:"Marcus aparece de la nada. «¿Un QUÉ para el perro?»"}}]},
 b:{say:"Su público espera. Cuarenta fotos majestuosas, cero publicaciones. ¿El plan de contenido de Frederick?",
    codex:"El trabajo creativo se hace por lotes: una sesión que produce un mes de contenido le gana a publicar cuando te acuerdas. La IA redacta los pies de foto; un humano aprueba antes de publicar — Frederick no puede aprobar, es un perro.",
    q:"El plan de contenido es…",
    ch:[{t:"Publicar cuando te acuerdes",out:{r:"mid",concept:"Lotes y programación",why:"Así va todo ahora — 40 fotos, cero publicaciones. El esfuerzo esporádico pierde contra un calendario aburrido, siempre. Medio crédito por honestidad.",beat:"Los fans de Frederick actualizan la página en vano."}},
        {t:"Día de lote mensual: la IA redacta, tú apruebas, un programador publica",out:{r:"ok",concept:"Lotes y programación",why:"Una hora al mes, la IA escribe, el humano conserva el criterio, el programador se encarga de recordar. La marca de Frederick: consistente.",beat:"La primera publicación programada llega a 200 me-gusta. Frederick sigue humilde."}},
        {t:"Dejar que la IA publique como Frederick, sin supervisión",out:{r:"bad",concept:"Lotes y programación",why:"El auto-posteo sin supervisión es como mueren las marcas. Sin revisión no hay piso.",beat:"En menos de una hora, la cuenta de Frederick promociona una cripto-estafa."}}]}}};
const QES=[
 {npc:"tovar",title:"El chatbot de 500 documentos",start:"a",nodes:{
  a:{say:"Los gerentes de tienda me llaman todo el día con preguntas de políticas. Quiero un chatbot sobre estos 500 documentos — y corporativo los reescribe cada mes.",
     codex:"Dos formas de darle conocimiento a un modelo: entrenarlo dentro del modelo (lento, caro, congelado al terminar) — o mantenerlo en un índice consultable que el modelo lee al responder, fresco al instante en que un documento se actualiza.",
     q:"Los documentos cambian cada mes. ¿Dónde vive el conocimiento?",
     ch:[{t:"Entrenar un modelo a medida con los documentos",out:{r:"bad",concept:"RAG vs fine-tuning",why:"Reentrenar cada mes es perseguir documentos viejos con dinero. Para cuando termina el entrenamiento, corporativo ya reescribió el manual.",beat:"Priya, en voz baja: «Así perdimos al líder anterior»."}},
         {t:"Indexar los documentos; el bot recupera las páginas correctas por pregunta",next:"b"},
         {t:"Pegar los 500 documentos en cada prompt",out:{r:"bad",concept:"RAG vs fine-tuning",why:"Pagarías por 500 documentos en cada pregunta — y los modelos pierden el foco en entradas enormes.",beat:"Marcus se materializa con una calculadora. De forma ominosa."}}]},
  b:{say:"Indexar — bien. Una cosa más: ayer un gerente preguntó por una política que no existe en ningún documento. ¿Qué debe hacer el bot?",
     codex:"Un bot anclado responde solo desde texto recuperado. Cuando la búsqueda vuelve vacía, lo honesto es admitirlo o derivar a un humano — lo peligroso es dejar que el modelo improvise.",
     q:"No existe documento que coincida. El bot debería…",
     ch:[{t:"Responder igual con conocimiento general — suele sonar bien",out:{r:"bad",concept:"Anclaje y rechazo",why:"«Suena bien» es como nace el Viernes de Churros Gratis. Una respuesta sin fuente es una alucinación esperando a un cliente.",beat:"Camila, a tres escritorios: «Ni se te ocurra»."}},
         {t:"Decir «no tengo esa política» y derivar la pregunta al equipo de operaciones",out:{r:"ok",concept:"Anclaje y rechazo",why:"Un bot que admite el hueco — y le pasa la pregunta a un humano — genera confianza y muestra qué documentos faltan.",beat:"El director asiente lento. «El bot sabe lo que no sabe. No como mi sobrino»."}},
         {t:"Que el bot pida disculpas y termine el chat",out:{r:"mid",concept:"Anclaje y rechazo",why:"Seguro, pero sin salida — sin derivación humana, la pregunta real muere en el chat. Medio crédito: nada falso, nada útil.",beat:"Entregado con incidentes. El gerente llama al director de todos modos."}}]}}},
 {npc:"camila",title:"Viernes de Churros Gratis",start:"a",nodes:{
  a:{say:"El bot piloto le acaba de prometer a un gerente el «Viernes de Churros Gratis — todas las sucursales». Esa política no existe. Los gerentes ya están preguntando.",
     codex:"Los modelos generan texto plausible — y cuando no saben, plausible significa inventado. Pedirlo por favor o bajar la aleatoriedad reduce variedad, no fabricación. Lo que funciona: las respuestas solo pueden venir de documentos recuperados, con cita.",
     q:"¿Cómo matas los churros imaginarios?",
     ch:[{t:"Agregar «no inventes cosas» a las instrucciones",out:{r:"mid",concept:"Control de alucinaciones",why:"Ayuda en los márgenes — y falla el día que importa. Las instrucciones empujan; no bloquean. Medio crédito por probar primero lo barato.",beat:"El bot inventa la «Amnistía del Martes de Tacos» una semana después."}},
         {t:"Poner la aleatoriedad en cero",out:{r:"bad",concept:"Control de alucinaciones",why:"Con temperatura cero el bot se equivoca con confianza, igual, todas las veces. Determinismo no es verdad.",beat:"Camila: «Ahora promete churros CONSISTENTEMENTE»."}},
         {t:"Anclar cada respuesta en texto recuperado — sin fuente, no hay respuesta",out:{r:"ok",concept:"Control de alucinaciones",why:"El anclaje ataca la causa: el bot dice solo lo que un documento real dice, lo cita, o admite que no tiene esa política.",beat:"Camila redacta el memo oficial de la Muerte del Viernes de Churros. Hay luto."}}]}}},
 {npc:"legal",title:"El contrato de 300 páginas",start:"a",nodes:{
  a:{say:"Necesito preguntas y respuestas sobre el contrato de franquicia de 300 páginas. El prototipo brilla en la página 20 y se estrella en la 200.",
     codex:"Cada solicitud tiene un presupuesto de tokens — pagas cada palabra enviada, cada vez — y los modelos atienden de forma dispareja las entradas muy largas: el medio se hunde. Menos texto, mejor elegido, le gana a mandarlo todo.",
     q:"¿Cómo cubres las 300 páginas?",
     ch:[{t:"Trocear el contrato; recuperar solo las secciones relevantes por pregunta",out:{r:"ok",concept:"Ventanas de contexto",why:"La recuperación envía las tres páginas que importan en vez de cobrarle a legal las 300 cada vez — y la calidad aguanta en la página 200 igual que en la 20.",beat:"Dana cierra su laptop satisfecha, lo que en términos legales es un abrazo."}},
         {t:"Consultar un resumen único del contrato",out:{r:"mid",concept:"Ventanas de contexto",why:"Sirve para «la idea general» — falla en las preguntas de cláusula por las que existen los contratos. Medio crédito: bien de acompañante, mal de respuesta.",beat:"Dana: «El resumen dice ‘aplican términos estándar’. ¿CUÁLES términos, bot?»."}},
         {t:"Comprar una ventana de contexto gigante y mandar las 300 páginas siempre",out:{r:"bad",concept:"Ventanas de contexto",why:"El medio se hunde igual, y ahora cada pregunta de estacionamiento cuesta un contrato entero en tokens.",beat:"Aparece Marcus. Escuchó la palabra «comprar»."}}]}}},
 {npc:"marcus",title:"El reporte matutino",start:"a",nodes:{
  a:{say:"Alguien gasta 40 minutos cada mañana sacando las ventas de ayer, formateando el reporte y enviándolo a dirección. ¿Puede tu… robot… hacerlo?",
     codex:"Una llamada simple al modelo solo escribe texto — no puede tocar una base de datos ni enviar correos. Dale herramientas (ejecutar consulta, enviar correo) y puede decidir cuál usar y en qué orden: eso es un agente. Los pasos fijos van en código; el criterio va en el modelo.",
     q:"¿Cómo se automatiza el reporte matutino?",
     ch:[{t:"Un mega-prompt de «haz el reporte»",out:{r:"bad",concept:"Agentes y herramientas",why:"Un reporte hermoso lleno de números imaginarios — sin herramientas no hay datos: pura ficción disfrazada de hoja de cálculo.",beat:"Dirección felicita el formato. Luego lee los números."}},
         {t:"Un agente con herramientas: consultar → formatear → enviar",out:{r:"ok",concept:"Agentes y herramientas",why:"Datos reales por herramientas reales, orquestado por el modelo. Cuarenta minutos se vuelven cero.",beat:"Marcus: «Si el robot se rompe, sale de tu presupuesto». Sonríe. Probablemente."}},
         {t:"Decirle a Marcus que los robots no están listos",out:{r:"bad",concept:"Agentes y herramientas",why:"Llevan tiempo listos. El CFO que te pide automatización no es la persona a la que conviene quedarle mal.",beat:"Marcus anota algo en una libretita. No te gusta la libretita."}}]}}},
 {npc:"marcus",title:"La factura",start:"a",nodes:{
  a:{say:"Esta factura. Diez mil tickets de soporte al mes, todos respondidos por el modelo más caro del mercado. La mayoría pregunta dónde está su pedido.",
     codex:"Hay modelos de varios tamaños y precios; los pequeños hacen el trabajo simple por centavos. Los sistemas pueden marcar sus propias respuestas de baja confianza — lo fácil va al modelo barato y solo lo difícil escala al premium.",
     q:"¿Cómo bajas la factura sin bajar la calidad?",
     ch:[{t:"Todo al modelo más barato, aceptar la caída",out:{r:"mid",concept:"Enrutamiento y costos",why:"La factura colapsa — y la calidad también, justo en los tickets difíciles que deciden si el cliente se queda. Medio crédito: buen instinto, sin salida de emergencia.",beat:"Las disputas de reembolso ahora las responde un modelo que cree que un churro es un zapato."}},
         {t:"Modelo barato primero; escalar lo difícil o dudoso al premium",out:{r:"ok",concept:"Enrutamiento y costos",why:"El barato se gana el pan con «¿dónde está mi pedido?»; el premium justifica su precio solo en el 10% espinoso. Misma calidad donde importa, fracción del gasto.",beat:"Marcus firma la factura. Viniendo de Marcus, son fuegos artificiales."}},
         {t:"Pedirle un descuento al proveedor",out:{r:"bad",concept:"Enrutamiento y costos",why:"Un descuento sobre la arquitectura equivocada sigue siendo la arquitectura equivocada, ahora con contrato más largo.",beat:"El proveedor manda una canasta de frutas. Marcus la devuelve."}}]}}},
 {npc:"priya",title:"El bot del 98%",start:"a",nodes:{
  a:{say:"El bot de cotizaciones acierta el 98% y envía todo solo. Aquí está el otro 2% — clientes reales, precios que pierden dinero real. A ventas le encanta. Finanzas encontró el 2%.",
     codex:"El nivel de automatización debe seguir el costo del error: automático donde equivocarse es barato, revisión humana donde es caro. Los puntajes de confianza separan cuál es cuál — solo lo dudoso espera a una persona.",
     q:"¿Lo lanzas, lo controlas o lo matas?",
     ch:[{t:"Lanzarlo — 98% es un diez",out:{r:"bad",concept:"Humano en el circuito",why:"98% es un diez en un examen. En precios auto-enviados son 200 cotizaciones malas al mes, en dinero real.",beat:"Finanzas abre una hoja de cálculo titulada «El 2%». Lleva tu nombre."}},
         {t:"Enviar las cotizaciones dudosas a revisión humana",next:"b"},
         {t:"Matarlo hasta que sea perfecto",out:{r:"bad",concept:"Humano en el circuito",why:"Perfecto nunca llega, y acabas de tirar el 98% que ahorraba horas todos los días.",beat:"Ventas hace una pequeña vigilia."}}]},
  b:{say:"De acuerdo — cola de revisión. Ahora la pregunta del árbol: ¿QUÉ cotizaciones esperan a un humano?",
     codex:"Revisarlo todo recrea el trabajo manual que automatizaste. No revisar nada es donde empezaste. La palanca es el umbral de confianza — más el costo del tipo de error: un precio demasiado bajo duele más que una cotización lenta.",
     q:"¿Qué va a la cola de revisión?",
     ch:[{t:"Todas — humanos revisan todo de nuevo",out:{r:"mid",concept:"Umbrales de confianza",why:"Seguro pero contraproducente: reconstruiste el trabajo de 40 horas con pasos extra. Medio crédito — sin pérdidas, sin palanca.",beat:"El revisor ahora revisa cotizaciones sobre revisar."}},
         {t:"Solo las de baja confianza y cualquiera sobre un tope de precio",out:{r:"ok",concept:"Umbrales de confianza",why:"La confianza captura la duda del modelo; el tope de precio captura los errores caros de los que está confiadamente equivocado. Dos redes, mínima fricción.",beat:"Ventas conserva su velocidad, finanzas su sueño, y Priya casi sonríe."}},
         {t:"Una muestra aleatoria del 10%",out:{r:"mid",concept:"Umbrales de confianza",why:"Muestrear mide la tasa de error — no detiene errores. Bien para monitorear, mal como única barrera. Medio crédito.",beat:"El 2% te saluda desde el 90% sin muestrear."}}]}}},
 {npc:"cto",title:"Las notas de Bayview",start:"a",nodes:{
  a:{say:"Nuestros médicos se ahogan en papeleo. Quiero resúmenes con IA de las notas de visita — pero cada nota está llena de datos de pacientes, y necesito no salir en las noticias.",
     codex:"Los datos de salud están regulados. Dos llaves hacen posible trabajar con LLM: enmascarar identificadores antes de que el modelo vea el texto, y usar un endpoint empresarial cubierto por un acuerdo firmado (BAA) que permite datos de salud. Los endpoints de consumo nunca están cubiertos.",
     q:"¿Cómo entregas los resúmenes?",
     ch:[{t:"Mandar las notas crudas a una IA de consumo",out:{r:"bad",concept:"Gobernanza de datos",why:"Esa es la opción que termina carreras — una brecha reportable con marca de tiempo.",beat:"En algún lugar, un oficial de cumplimiento despierta sudando frío, sin saber por qué."}},
         {t:"Enmascarar identificadores + endpoint cubierto por BAA + registrar todo",out:{r:"ok",concept:"Gobernanza de datos",why:"El modelo ve solo lo necesario, en infraestructura autorizada a verlo, con rastro de auditoría. El camino estándar y defendible.",beat:"Dr. Okafor: «Por fin. Alguien que ya hizo esto en salud»."}},
         {t:"Negarse: la IA no puede tocar datos de salud",out:{r:"mid",concept:"Gobernanza de datos",why:"Cero riesgo, cero ayuda — y alguien menos cuidadoso dirá que sí. Medio crédito por cautela sin oficio.",beat:"Los médicos siguen ahogándose, pero en regla."}}]}}},
 {npc:"junior",title:"El prompt de Theo",start:"a",nodes:{
  a:{say:"¡Cambié el prompt del bot de soporte y el demo mejoró MUCHÍSIMO! ¿Podemos lanzar hoy? ¿Porfa? Ya le dije a mi mamá.",
     codex:"Un buen demo es una anécdota. Los cambios de prompt arreglan un caso y rompen cinco en silencio. Los equipos mantienen un set de evaluación — casos reales con respuestas correctas conocidas — y puntúan cada cambio antes de lanzar. Tests unitarios, pero para IA.",
     q:"¿El prompt de Theo se lanza hoy?",
     ch:[{t:"Lanzarlo — ambos lo vieron mejorar",out:{r:"bad",concept:"Evaluaciones y regresión",why:"El demo mostró un caso. La evaluación habría mostrado los dos flujos de reembolso que rompió. Ahora los encontrarán los clientes.",beat:"La mamá de Theo está orgullosa. La cola de reembolsos no."}},
         {t:"Correr el set de evaluación; lanzar mañana si el puntaje aguanta",out:{r:"ok",concept:"Evaluaciones y regresión",why:"Una hora de evaluación atrapa lo que los demos esconden — encuentra dos casos de reembolso rotos. Theo lanza mañana, correctamente, y aprende el ritual.",beat:"Theo le compra café a Priya por una semana. Arco de crecimiento iniciado."}},
         {t:"Preguntarle a otra IA cuál prompt es mejor",out:{r:"mid",concept:"Evaluaciones y regresión",why:"IA-como-juez es una técnica real — dentro de un arnés de evaluación con criterios definidos. Como oráculo de intuiciones, es una moneda con opiniones. Medio crédito.",beat:"El modelo juez dice que ambos prompts están «¡geniales!». Lo dice de todo."}}]}}},
 {npc:"tovar",title:"El plan enmicado",start:"a",nodes:{
  a:{say:"Una cosa más — los gerentes quieren transcripción de reuniones en la app. Theo tiene un plan de seis meses para construir voz-a-texto desde cero. Lo enmicó.",
     codex:"Algunas capacidades de IA son commodities — transcripción, traducción, OCR — vendidas como APIs excelentes por centavos. La diferenciación vive en lo que tu producto hace con el resultado, no en reconstruir el commodity.",
     q:"¿Seis meses para construirlo, o…?",
     ch:[{t:"Construir voz-a-texto desde cero",out:{r:"bad",concept:"Construir vs comprar",why:"Seis meses reconstruyendo lo que cuesta centavos por minuto, para alcanzar una calidad que la API ya supera. Nadie lo notará — excepto Marcus.",beat:"Lo enmicado era lo mejor del plan."}},
         {t:"Integrar una API probada de transcripción; construir las funciones encima",out:{r:"ok",concept:"Construir vs comprar",why:"Dos semanas para integrar, y el equipo construye lo que los gerentes pidieron — lo que va sobre la transcripción. Construye la última milla, compra el commodity.",beat:"Theo des-enmica el plan. En silencio."}},
         {t:"Contratar transcriptores humanos",out:{r:"bad",concept:"Construir vs comprar",why:"Más lento, más caro, y no escala pasada la tercera reunión. Estamos en 2026.",beat:"La vacante recibe tres postulaciones. Todas de bots."}}]}}},
 {npc:"ceo",title:"El silencio de 8 segundos",start:"a",nodes:{
  a:{say:"Demo final. Tu agente telefónico da respuestas brillantes… ocho segundos después de que el cliente deja de hablar. Los conté. Dos veces. La gente cuelga.",
     codex:"En IA en tiempo real, la gente juzga el tiempo hasta la primera palabra, no el tiempo de la respuesta completa. Dos palancas: transmitir la respuesta en streaming para que empiece a hablar mientras se genera, y abrir con un modelo pequeño y rápido mientras lo pesado alcanza por detrás.",
     q:"Mata el silencio de ocho segundos:",
     ch:[{t:"Esperar hardware más rápido",out:{r:"bad",concept:"Ingeniería de latencia",why:"La latencia es un problema de diseño que arreglas este sprint, no un problema de hardware que otro arregla el año que viene.",beat:"El CEO mira su reloj por tercera vez. Hace eco."}},
         {t:"Streaming en la respuesta; abrir con un modelo pequeño y rápido",next:"b"},
         {t:"Poner música de espera",out:{r:"bad",concept:"Ingeniería de latencia",why:"Ahora son ocho segundos de jazz antes de la decepción.",beat:"Camila veta la licencia de smooth jazz."}}]},
  b:{say:"Priya, parchando en vivo: «El streaming quedó. Última llamada — ¿qué métrica va en el tablero de lanzamiento?»",
     codex:"Obtienes lo que mides. El tiempo total esconde el arreglo; el tiempo hasta la primera palabra es lo que la gente siente — con el tiempo total y la calidad al lado, no en su lugar.",
     q:"La métrica principal de latencia es…",
     ch:[{t:"Tiempo total promedio de respuesta",out:{r:"mid",concept:"Métricas de latencia",why:"Real, pero titular equivocado — una respuesta lenta en streaming SE SIENTE instantánea, y esta métrica no lo ve. Medio crédito; déjala como secundaria.",beat:"El tablero dice «más lento». Los clientes dicen «por fin»."}},
         {t:"Tiempo hasta la primera palabra",out:{r:"ok",concept:"Métricas de latencia",why:"Es el momento en que el silencio termina — lo que la gente juzga. Mide el tiempo total y la calidad al lado; titula con esta.",beat:"Menos de un segundo. El CEO guarda el reloj. Priya sonríe. Hay testigos."}},
         {t:"Número de personas que cuelgan",out:{r:"mid",concept:"Métricas de latencia",why:"Gran métrica de resultado — pero es una alarma tardía, no un volante. Medio crédito.",beat:"«Buenas noticias: caen los cuelgues. Malas: lo supimos una semana tarde»."}}]}}},
 {npc:"rosa",title:"El teléfono no para",start:"a",nodes:{
  a:{say:"Mijo, el teléfono suena todo el día — pedidos, preguntas, «¿tienen birria?». Pierdo la mitad de las llamadas mientras cocino. Dicen que un robot puede contestar. Bueno. ¿Pero puede tomar pedidos SIN arruinarlos?",
     codex:"Un agente de voz puede tomar pedidos por teléfono — el truco es la estructura. Lo hablado se convierte en un pedido estructurado (platillos, tamaños, extras, precio) contra el menú real, y se lo lee de vuelta al cliente para confirmar antes de que cuente. Adivinar con texto libre es como terminas con tres birrias sorpresa.",
     q:"¿Cómo debe tomar pedidos el agente telefónico?",
     ch:[{t:"Que converse libremente y anote lo que escuche",out:{r:"bad",concept:"Salidas estructuradas",why:"Texto libre significa que «horchata grande» se vuelve «¿la orchata grande?» se vuelve tickets misteriosos. Sin estructura no hay comanda confiable.",beat:"El ticket #4 dice «birria??? ¿3 quizás?». La cocina llora."}},
         {t:"Emparejar cada pedido con el menú real como items estructurados, y leerlo de vuelta para confirmar",next:"b"},
         {t:"Seguir perdiendo llamadas — es más auténtico",out:{r:"bad",concept:"Salidas estructuradas",why:"Llamadas perdidas son ingresos perdidos — un tercio de los pedidos de Rosa llegan por teléfono.",beat:"Al otro lado de la ciudad, el robot de la competencia dice «gracias por su orden»."}},
         {t:"Contratar a alguien solo para contestar el teléfono",out:{r:"mid",concept:"Salidas estructuradas",why:"Un humano funciona — con sueldo, descansos, y renuncias en el peor momento. Opción real, costo pesado para un problema resoluble. Medio crédito.",beat:"La nueva contratación renuncia tras un solo sábado en friega."}}]},
  b:{say:"¡Funciona, mijo! Pero anoche alguien pidió «el paquete de banquete de bodas para 200 personas» — y el robot dijo que SÍ, feliz de la vida. Nosotros no hacemos bodas.",
     codex:"Los agentes necesitan límites explícitos: qué pueden vender, topes de tamaño de pedido, y la regla de pasarle a un humano cualquier solicitud inusual. La confirmación protege al cliente; los límites protegen a Rosa.",
     q:"Arregla el entusiasmo del robot:",
     ch:[{t:"Solo menú + tope de pedido + lo inusual va al teléfono de Rosa",out:{r:"ok",concept:"Límites del agente",why:"Vender solo lo que existe, hasta límites sensatos, y escalar lo raro a un humano. De las bodas decide Rosa — no el robot.",beat:"El robot transfiere cortésmente una consulta de quinceañera. Rosa negocia como campeona."}},
         {t:"Apagar el robot de noche",out:{r:"mid",concept:"Límites del agente",why:"Esquiva el error esquivando también los ingresos. Medio crédito — seguro, pero pequeño.",beat:"Los noctámbulos piden pizza. Traidores."}},
         {t:"Que improvise — el cliente siempre tiene la razón",out:{r:"bad",concept:"Límites del agente",why:"Un agente sin límites prometerá 200 birrias y un mariachi. El costo del error no tiene techo.",beat:"En algún lugar, Marcus siente una perturbación que no puede explicar."}},
         {t:"Que el robot ofrezca extras en todo para subir ventas",out:{r:"bad",concept:"Límites del agente",why:"Un agente optimizando ingresos sin límites quema la confianza — lo que puede OFRECER también es decisión de límites.",beat:"Una abuelita que pide un café recibe oferta del paquete de fiesta. Dos veces."}}]}}},
 {npc:"chuy",title:"La prep del viernes",start:"a",nodes:{
  a:{say:"Cada viernes adivino cuánta barbacoa preparar. Si le atino bajo — se acaba a las 8 y la gente llora. Si le atino alto — el Chuy del domingo come sobras tristes tres días. Tiene que haber una mejor manera, ¿no?",
     codex:"Pronosticar le gana al instinto: promedia los últimos viernes, ajusta por lo distinto de esta semana (quincena, clima, eventos), y registra qué tan equivocado estuviste para mejorar cada semana. Sobreproducir es dinero a la basura; quedarse sin producto es clientes a la basura.",
     q:"¿Cuánta barbacoa para el viernes?",
     ch:[{t:"Lo de siempre — al tanteo",out:{r:"mid",concept:"Pronóstico de demanda",why:"El instinto trajo a Chuy hasta aquí — a veces acierta, nunca se mide, imposible de mejorar. Medio crédito por sobrevivir al puro oficio.",beat:"Viernes, 8:15pm: «no hay». Se escuchan corazones romperse."}},
         {t:"Promediar los últimos 8 viernes, ajustar por quincena y clima, y registrar el error semanal",out:{r:"ok",concept:"Pronóstico de demanda",why:"Un pronóstico simple más registro del error se vuelve más listo cada semana. Esto es ciencia de datos con mandil.",beat:"Chuy pega el pronóstico en el refri. Se vuelve ley."}},
         {t:"Doblar todo y vender sobras el sábado",out:{r:"bad",concept:"Pronóstico de demanda",why:"El desperdicio como estrategia — el margen muere calladito en el cuarto frío.",beat:"Una torre de barbacoa dominical. Hasta Frederick, de visita, dice que no."}},
         {t:"Comprar primero una gran plataforma de pronósticos con IA",out:{r:"mid",concept:"Pronóstico de demanda",why:"Herramientas antes que disciplina de datos es al revés — el promedio simple con registro de error gana hasta que los datos ameriten plataforma. Medio crédito.",beat:"La llamada de implementación dura más que el servicio del viernes."}}]}}},
 {npc:"guero",title:"El presupuesto",start:"a",nodes:{
  a:{say:"¡Jefe! Una clienta quiere cotización para remodelar un local al otro lado de la ciudad. Mandó treinta fotos y quiere el número HOY. Antes, yo manejaba hasta allá, medía dos horas y adivinaba el resto. Tú eres el de la IA — impresióname.",
     codex:"Los modelos de visión pueden leer medidas desde fotos: áreas de muros, instalaciones, daños, materiales. El patrón confiable: la IA redacta las partidas desde las fotos — cantidades, materiales, mano de obra — y un humano verifica precios y rincones raros antes de enviarla. Rápido Y defendible.",
     q:"¿Cómo se arma la cotización?",
     ch:[{t:"Calcular a ojo desde las fotos, con experiencia",out:{r:"mid",concept:"Presupuestos con visión",why:"La experiencia es real — pero adivinar sin medir gana trabajos que pierden dinero. Medio crédito por las canas.",beat:"El bigote de Don Güero tiembla. Sabe que tienes razón."}},
         {t:"La IA redacta partidas desde las fotos; Güero verifica materiales y precios antes de enviar",next:"b"},
         {t:"Prometer ganarle a cualquier otra cotización y ya verás después",out:{r:"bad",concept:"Presupuestos con visión",why:"Ganar por precio sin conocer tus costos es como mueren las constructoras con la agenda llena.",beat:"Lupe, sin levantar la vista: «Así cayó la empresa pasada»."}},
         {t:"Mandar a un aprendiz a medir todo a mano hoy",out:{r:"mid",concept:"Presupuestos con visión",why:"Preciso — y lento. La cotización llega tarde, y las tardías pierden. Medio crédito por rigor sin velocidad.",beat:"El aprendiz mide precioso. La clienta firmó con otros al mediodía."}}]},
  b:{say:"¡Ganamos el trabajo, jefe! Pero ahora la clienta dice: «ya que están ahí, agréguenme un bañito». UN BAÑITO. ¿Qué le digo?",
     codex:"Los cambios de alcance son donde se desangran las obras. La disciplina es la orden de cambio: cada extra se escribe con su precio e impacto en el calendario, y se aprueba ANTES de trabajar. La IA la redacta en minutos desde el presupuesto original — sin pena, puro papel.",
     q:"El «bañito» se maneja con…",
     ch:[{t:"Hacerlo y ya — cliente contenta",out:{r:"bad",concept:"Órdenes de cambio",why:"Baños gratis hoy, quiebra mañana. El alcance no cobrado es el asesino silencioso de las buenas cuadrillas.",beat:"La cuadrilla lo construye precioso. Nadie lo paga."}},
         {t:"Orden de cambio escrita — precio e impacto en tiempo, redactada por IA, aprobada antes de trabajar",out:{r:"ok",concept:"Órdenes de cambio",why:"La IA convierte el presupuesto en orden de cambio en minutos; la clienta firma sabiendo exactamente qué cuesta. Todos quedan amigos Y solventes.",beat:"La clienta firma. Don Güero enmarca la orden de cambio como diploma."}},
         {t:"Negarse a todo cambio — el contrato es el contrato",out:{r:"mid",concept:"Órdenes de cambio",why:"Protege el margen, pierde la relación — y las remodelaciones SIEMPRE cambian. Medio crédito por carácter, cero por flexibilidad.",beat:"La clienta llama a otros para el siguiente trabajo. Y el siguiente."}},
         {t:"Hacerlo y colarlo calladito en la factura final",out:{r:"bad",concept:"Órdenes de cambio",why:"Los cobros sorpresa son como se pierde la confianza — y a veces se ganan citas en el juzgado. Primero papel, luego trabajo.",beat:"La factura final desata una discusión a gritos en dos idiomas."}}]}}},
 {npc:"lupe",title:"El purgatorio de permisos",start:"a",nodes:{
  a:{say:"Tres proyectos están muertos porque los permisos no se han metido. Los mismos formularios, la misma ciudad, cada vez — datos del dueño, alcance, lista de planos, cuotas. Me gasto los domingos copiando los mismos datos en las mismas casillas. En algún lugar de esto debe haber dignidad.",
     codex:"El papeleo repetitivo es la cancha del automatizado de documentos: los datos del proyecto ya existen, así que la IA puede llenar los formularios estándar y seguir el estado de cada permiso. El humano revisa antes de presentar — un permiso mal hecho es peor que uno lento.",
     q:"¿Cómo se resuelven los permisos?",
     ch:[{t:"Buscar a un conocido que conoce a alguien en el municipio",out:{r:"bad",concept:"Automatización de documentos",why:"El conocido se jubila, el atajo se vuelve escándalo, y los proyectos siguen muertos. Eso no es un sistema.",beat:"El primo del conocido cotiza una «cuota de consultoría». Lupe cuelga."}},
         {t:"La IA llena los formularios desde los datos del proyecto, Lupe revisa antes de presentar, y un tablero sigue cada permiso",out:{r:"ok",concept:"Automatización de documentos",why:"Los datos existen una vez, los formularios se llenan solos, el humano firma, y nada vuelve a perderse en el purgatorio. Los domingos regresan a Lupe.",beat:"Tres permisos presentados antes del almuerzo. Lupe toma un fin de semana de verdad. El municipio está confundido."}},
         {t:"Seguir a mano — es la tradición",out:{r:"mid",concept:"Automatización de documentos",why:"Funciona, lento, y se come a la presupuestista que debería estar presupuestando. Medio crédito por confiable, al costo de los domingos.",beat:"El café de Lupe se enfría sobre el formulario B-247. Otra vez."}},
         {t:"Tercerizar todos los permisos a una consultora",out:{r:"mid",concept:"Automatización de documentos",why:"Funciona — con honorarios, para siempre, y la capacidad nunca llega a casa. Medio crédito: delegado, no resuelto.",beat:"La consultora usa la misma herramienta de IA. Lupe observa, facturada."}}]}}},
 {npc:"priya",title:"Dilo para que sea verdad",start:"a",nodes:{
  a:{say:"Las respuestas del bot de soporte SUENAN geniales — seguras, pulidas, equivocadas una de cada diez veces. Nadie sabe cuál. A marketing le encanta el tono. Yo odio el tono. Arregla la redacción.",
     codex:"La confianza se construye con lenguaje calibrado: instrucciones que hacen que el bot cite su fuente, marque lo incierto como incierto, y diga «no lo sé» cuando nada respalda la respuesta. «Sé preciso» es una vibra — citar, matizar y rehusar son conductas.",
     q:"¿Qué va en las instrucciones del bot?",
     ch:[{t:"Escribir «sé preciso y útil» al inicio",out:{r:"mid",concept:"Lenguaje calibrado",why:"Una vibra, no una conducta. Los modelos siguen verbos concretos; «sé preciso» no mide nada. Medio crédito — inofensivo, inútil.",beat:"El bot sigue equivocándose con confianza, pero ahora con cortesía."}},
         {t:"Citar la fuente de cada afirmación, marcar lo incierto como incierto, y decir «no lo sé» cuando nada lo respalda",next:"b"},
         {t:"Que suene MÁS seguro — a los clientes les gusta la certeza",out:{r:"bad",concept:"Lenguaje calibrado",why:"Redacción segura sobre respuestas equivocadas es como muere la confianza a escala. Eso es pulir el fracaso.",beat:"Marketing aplaude. Camila abre una hoja de cálculo nueva."}},
         {t:"Agregar un descargo legal a cada respuesta",out:{r:"mid",concept:"Lenguaje calibrado",why:"Cubrirse no es sincerarse — al tercer mensaje, los usuarios ya aprendieron a saltárselo. Medio crédito por instinto de abogado.",beat:"Los usuarios pasan el descargo a velocidad récord. Todos."}}]},
  b:{say:"Mejor. Ahora la de verdad: alguien llama y pregunta «¿cuántas sucursales aceptan la app?» — la búsqueda no encuentra nada actual. El bot tiene que decir ALGO. Redáctalo.",
     codex:"Cuando no puedes verificar, la forma confiable es: afirmar lo que SÍ puedes confirmar, nombrar lo que no, y entregar el camino a la respuesta. La precisión sobre tus propios límites es a lo que suena la exactitud.",
     q:"La mejor respuesta del bot es…",
     ch:[{t:"«¡Unas 300 sucursales!» — seguro le atina",out:{r:"bad",concept:"Afirmaciones verificables",why:"Una suposición con confianza es una mentira con buena postura. Un número equivocado desteje todos los correctos anteriores.",beat:"Eran 41. En la línea había una periodista."}},
         {t:"«No puedo verificar el número actual. Al último corte eran 38 — aquí está la lista en vivo.»",out:{r:"ok",concept:"Afirmaciones verificables",why:"Confirma lo conocido, nombra lo desconocido, entrega el camino. Esa redacción ES el producto de confianza.",beat:"Priya lo lee dos veces. «Publica esa redacción.» El mayor elogio que conoce."}},
         {t:"«No puedo responder esa pregunta.»",out:{r:"mid",concept:"Afirmaciones verificables",why:"Honesto pero flojo — rehusar todo lo no verificable tira la verdad parcial que SÍ tienes. Medio crédito.",beat:"La persona le pregunta a un humano, que le lee el mismo último corte."}},
         {t:"Responder normal y esconder «las cifras pueden variar» al final",out:{r:"mid",concept:"Afirmaciones verificables",why:"Incertidumbre en la letra chica es certeza en el titular. La ubicación también es redacción. Medio crédito.",beat:"Nadie lee la nota tres al pie. Nunca."}}]}}},
 {npc:"xochi",title:"El drop de collares",start:"a",nodes:{
  a:{say:"¡Ah, la persona de IA! Mira — La Obra construye el barrio, yo lo visto. Quiero una línea de collares para las mascotas del rumbo: Frederick, Canela, todo el elenco. Sé dibujar, pero estas herramientas de imágenes con IA… ¿cómo DISEÑAMOS con ellas sin perder el oficio?",
     codex:"Los modelos de imágenes son motores de variaciones, no diseñadores. El patrón que funciona: la diseñadora define el brief, la IA genera decenas de direcciones, el humano cura y refina las ganadoras — y la elegida solo se vuelve real cuando es una especificación estructurada (un tech pack): materiales, medidas, colores. El gusto sigue siendo humano; la máquina pone el volumen.",
     q:"¿Cómo se diseña la línea de collares?",
     ch:[{t:"Un prompt, la primera imagen, directo a producción",out:{r:"bad",concept:"Diseño asistido por IA",why:"Sin curaduría, sin especificación, sin tallas — una primera salida es un mood, no un producto. Producción necesita medidas, no vibras.",beat:"La muestra llega en talla caballo. Frederick se niega a comentar."}},
         {t:"La IA genera variaciones sobre el brief de Xochi; ella cura, y la elegida se vuelve tech pack — materiales, tallas, colores",next:"b"},
         {t:"Copiar el collar de esa diseñadora famosa y que la IA lo restilice un poco",out:{r:"bad",concept:"PI y originalidad",why:"Una copia restilizada sigue siendo una copia — radiactiva en lo legal y hueca en lo creativo. La IA hace la imitación más rápida, no legal, y el barrio merece su propio estilo.",beat:"Dana aparece en la puerta del Estudio con un cese y desista. Solo para que sepas cómo se ve uno."}},
         {t:"Dibujar todo a mano como siempre, sin IA",out:{r:"mid",concept:"Diseño asistido por IA",why:"El oficio es real y el gusto es el punto — pero una diseñadora explorando cinco direcciones a mano pierde contra la misma curando cincuenta. Medio crédito por los estándares.",beat:"Semana dos: tres bocetos hermosos, noventa ideas sin explorar."}}]},
  b:{say:"El tech pack quedó precioso. Ahora el lanzamiento — son atuendos virtuales para las mascotas del pueblo. ¿Cómo sacamos la línea?",
     codex:"La curaduría es control de calidad para bienes creativos. Drops pequeños con revisión humana — ¿cada pieza le queda a cada cuerpo para el que se vende? — mantienen un catálogo que vale la pena. Auto-generar publicaciones infinitas inunda el estante de basura, y «todo gratis para siempre» solo significa que el trabajo no puede continuar.",
     q:"La estrategia del drop es…",
     ch:[{t:"Drops pequeños y curados; cada pieza probada en cada cuerpo antes de publicarse",out:{r:"ok",concept:"Curaduría como QA",why:"Cada drop es lo bastante pequeño para revisarse y lo bastante especial para desearse. La mentalidad de evals, aplicada a la moda: se prueba en cada tipo de cuerpo antes de salir.",beat:"El primer drop se agota antes del atardecer. Frederick modela el collar dorado con una dignidad insoportable."}},
         {t:"Auto-generar y auto-publicar artículos nuevos a diario",out:{r:"bad",concept:"Curaduría como QA",why:"Un catálogo infinito sin curar es un basurero con buscador. Nadie navega la basura dos veces.",beat:"El artículo #4,072 es un collar con tres hebillas y ningún agujero. Ya lo compró una paloma confundida."}},
         {t:"Todo gratis, para siempre, para todos",out:{r:"mid",concept:"Curaduría como QA",why:"Generoso — e insostenible. Lo gratis es táctica de lanzamiento, no un plan; la línea muere cuando el trabajo no se paga solo. Medio crédito por el corazón.",beat:"Mes dos: Xochi acepta un mural en silencio para financiar el collar tres."}}]}}},
 /* ---------- El Mercado Robles · el pack de product manager de IA (Semana Dos, capítulo uno) ----------
    Doña Chelo lo quiere todo al mismo tiempo. El trabajo es decidir qué se construye de verdad. */
 {npc:"chelo",title:"Todo al mismo tiempo",start:"a",nodes:{
  a:{say:"Mijo, siéntate. Hice una lista. Una app para pedidos. Un robot para el teléfono. Algo que sepa cuándo se pican los tomates. Una cosa para Instagram. Una máquina que me diga qué comprar el lunes. Mi sobrino dice que necesito página web. Ah, y la impresora no sirve.",
     codex:"Once deseos no son un plan. Lo primero que se construye es donde el dolor es frecuente, medible y de alguien que de verdad va a usar la solución — no lo que suena más impresionante al contarlo. Todo lo demás se queda en la lista y espera su turno.",
     q:"¿Por dónde empiezas?",
     ch:[{t:"Construir la app de pedidos — es la idea más grande de la lista",out:{r:"bad",concept:"Alcance",why:"Lo más grande no es lo primero. La app de pedidos toca proveedores, inventario, pagos y a todos los clientes a la vez — seis meses antes de que alguien pueda decir si sirvió.",beat:"Doña Chelo asiente con cortesía. Nando deja de hacer contacto visual."}},
         {t:"Preguntar cuál de todas le cuesta más horas en una semana normal, y construir esa",next:"b"},
         {t:"Hacerlas todas, pero chiquitas — un poquito de cada una",out:{r:"bad",concept:"Alcance",why:"Once medias cosas son once cosas que mantener y ninguna en la que se pueda confiar. Medio bot de teléfono sigue contestando mal el teléfono.",beat:"Para el jueves hay once pestañas abiertas y nadie sabe cuál es la buena."}},
         {t:"Arreglar la impresora",out:{r:"mid",concept:"Alcance",why:"¿Honestamente? Destrabar a la persona que hace el trabajo gana contra un piloto que nadie pidió. Pero la impresora no es el problema por el que te contrató. Medio crédito por leer el ambiente.",beat:"La impresora sirve. Doña Chelo está genuinamente feliz. La lista sigue midiendo once."}}]},
  b:{say:"El teléfono. Es el teléfono. Cuarenta llamadas al día — ¿tienen masa?, ¿a qué hora cierran?, ¿tienen el queso de rancho? — y cada una le quita a Perla de la caja.",
     codex:"Antes de construir, define qué significa que funcione en un número que alguien ya lleva. No “el bot es inteligente” sino “Perla se levanta de la caja menos de cinco veces al día”. Una métrica de éxito escrita después del lanzamiento es un cuento, no una medición.",
     q:"Empiezas a construir. ¿Qué defines primero?",
     ch:[{t:"Cuántas de las cuarenta tiene que resolver para que Chelo lo considere digno de quedarse",out:{r:"ok",concept:"Definición de terminado",why:"Ese número es el proyecto entero. Te dice qué construir, cuándo parar y — la parte que todos se saltan — cuándo admitir que no funcionó.",beat:"Chelo lo piensa. “Si agarra treinta y no miente, me lo quedo.” Escribe eso en la pared."}},
         {t:"Cuál modelo usar",out:{r:"bad",concept:"Definición de terminado",why:"El modelo es la decisión más barata de todas y la más fácil de cambiar después. Escogerlo primero es elegir el martillo antes de ver la pared.",beat:"Nando, con recelo: “…¿es esa cosa que mi primo trae en el celular?”"}},
         {t:"El nombre y el logo",out:{r:"mid",concept:"Definición de terminado",why:"Va a importar para las abuelas que tienen que confiar en él — pero bautizar algo antes de definirlo es cómo terminas con una nada bellamente marcada. Medio crédito.",beat:"Perla ya dibujó un logo. Y hay que decirlo: está excelente."}}]}}},
 {npc:"chelo",title:"La prueba de la abuela",start:"a",nodes:{
  a:{say:"Perla dice que lo del teléfono debería ser una app. Mijo — mis clientas son señoras que contestan el celular como si fuera teléfono de casa. Doña Meche me habla para preguntar si tengo masa. Me habla cada martes desde hace nueve años.",
     codex:"El usuario que tienes no es el usuario del pitch. Una herramienta que exige descarga, cuenta y datos la usan los que ya tenían las tres. Encuentra a la gente en el canal que ya usa, o acepta que construiste para otro barrio.",
     q:"¿Cómo se contestan las preguntas de Doña Meche?",
     ch:[{t:"Una app — es la experiencia más limpia",out:{r:"bad",concept:"Encontrar al usuario donde está",why:"¿Limpia para quién? Una app es una descarga, un login y un tutorial parados entre Meche y la palabra sí. Va a seguir llamando, y ahora además tienes una app que mantener.",beat:"Nueve instalaciones. Seis son Perla probándola. Una es Chava, sin querer."}},
         {t:"El mismo número al que ya llama — el bot contesta y pasa a una persona cuando no puede",out:{r:"ok",concept:"Encontrar al usuario donde está",why:"Cero comportamiento nuevo para una clienta de nueve años. El canal es el mismo; solo cambia lo que pasa después del segundo timbre. Y el pase a humano hace que un error cueste una transferencia, no una clienta.",beat:"Meche nunca se entera de que algo cambió. Ese es exactamente el punto."}},
         {t:"Enseñarle a las clientas a usar WhatsApp",out:{r:"mid",concept:"Encontrar al usuario donde está",why:"Algunas sí — medio barrio ya está ahí. Pero “primero cambia a tus clientes” es un plan con un primer paso larguísimo. Medio crédito.",beat:"Doña Chelo, seca: “Tú le enseñas. Yo miro.”"}},
         {t:"Poner un letrero en la puerta con los horarios",out:{r:"mid",concept:"Encontrar al usuario donde está",why:"Barato, real, y mata las llamadas de quien está parado en la puerta. Meche no está parada en la puerta. Medio crédito por intentar primero lo más barato.",beat:"Ponen el letrero. Suena el teléfono. Es Meche."}}]}}},
 {npc:"nando",title:"El atajo de Nando",start:"a",nodes:{
  a:{say:"Antes de que cambies nada — yo ya hago esto. Llega el camión, le tomo foto a cada caja, las fotos van a una carpeta por fecha, las cuentas van a una hoja de cálculo en mi teléfono. Cuarenta minutos. Nunca se ha equivocado.",
     codex:"El atajo ES el documento de requerimientos. Alguien ya resolvió el problema mal-pero-bien, y cada rareza de su proceso codifica una restricción real. Reemplázalo sin leerlo y el despliegue muere de lo de siempre: la herramienta se lanza, la persona conserva su hoja de cálculo, y ahora hay dos sistemas.",
     q:"¿Qué haces con la hoja de Nando?",
     ch:[{t:"Reemplazarla — el sistema nuevo hace todo eso automáticamente",out:{r:"bad",concept:"Respetar el atajo",why:"Acabas de borrar el único registro de inventario correcto del edificio, junto con cuarenta minutos de criterio que Nando aplica sin darse cuenta. Va a conservar la hoja en secreto. Siempre lo hacen.",beat:"Tres semanas después: dos inventarios que no coinciden. Adivina cuál le cree Chelo."}},
         {t:"Acompañarlo en una entrega completa y ver a dónde se van de verdad los cuarenta minutos",next:"b"},
         {t:"Dejarla en paz — funciona",out:{r:"mid",concept:"Respetar el atajo",why:"¡No está mal! De verdad funciona. Pero cuarenta minutos diarios de una persona fotografiando cajas es justo la forma de lo que vale la pena mejorar — solo hay que mejorarlo con él, no contra él. Medio crédito por no romper lo que sirve.",beat:"Nando, desconfiado: “¿Ya? ¿No me vas a hacer usar una app?”"}}]},
  b:{say:"Treinta de los cuarenta son las facturas de los proveedores. La mitad a mano. Uno escribe en español, otro en inglés con los nombres mal, y el del pescado nada más pone PESCADO y un número.",
     codex:"Apunta al paso más lento en el que la máquina es genuinamente mejor — leer documentos desordenados — y déjale a la persona el paso que necesita criterio: decidir si la entrega realmente está bien. Automatiza el tecleo, no la confianza.",
     q:"Entonces lo que se construye es…",
     ch:[{t:"Leer las facturas automáticamente; Nando confirma las cuentas en pantalla en una sola pasada",out:{r:"ok",concept:"Automatizar el paso, no el puesto",why:"Treinta minutos se vuelven cinco, Nando sigue viendo cada entrega, y la revisión que atrapa un faltante se queda donde siempre estuvo — en su cabeza.",beat:"Nando lo lee dos veces. “¿Y yo sigo diciendo sí o no?” Sí. “Órale. Órale, así está bien.”"}},
         {t:"Automatización completa — entra la factura, se actualiza el inventario, sin paso humano",out:{r:"bad",concept:"Automatizar el paso, no el puesto",why:"El del pescado escribe PESCADO y un número. No existe una versión de esto donde nadie revise. Quita la revisión y la primera entrega mala se vuelve un número equivocado permanente.",beat:"El sistema recibe con toda confianza 400 kilos de PESCADO. Eran 40."}},
         {t:"Exigir a los proveedores facturas digitales bien hechas",out:{r:"mid",concept:"Automatizar el paso, no el puesto",why:"La solución correcta a largo plazo, y completamente fuera de tu control. No puedes lanzar un proyecto cuyo primer paso es “nueve negocios ajenos cambian su forma de trabajar”. Medio crédito — empieza a pedirlo, no lo esperes.",beat:"Nando se ríe seis segundos completos. “El del pescado. Facturas digitales. El del PESCADO.”"}}]}}},
 {npc:"perla",title:"La fila en la caja",start:"a",nodes:{
  a:{say:"Okay, o sea — todo el mundo me pregunta si aceptamos tarjeta por menos de cinco dólares y es SÚPER molesto. ¿La IA puede hacer eso? Ah, y a veces preguntan qué lleva el mole y tengo que ir a buscar a Doña Chelo, pero eso pasa como dos veces por semana.",
     codex:"La petición más ruidosa casi nunca es la más grande. Alcance por frecuencia por costo-de-fallar le gana a quien preguntó más recientemente y con más sentimiento. Y la buena noticia: una pregunta constante con una sola respuesta fija normalmente no es un problema de IA.",
     q:"¿Cuál construyes?",
     ch:[{t:"La del mínimo de tarjeta — es la pregunta más común por mucho",out:{r:"mid",concept:"Priorizar por alcance",why:"Buen instinto, herramienta equivocada. Una pregunta con una sola respuesta que no cambia es un letrero, no un sistema. Hacerle un bot es gastar un mes en una tarjeta plastificada. Medio crédito por leer bien el volumen.",beat:"Perla se queda viendo el letrero que imprimes. “…¿ya? ¿Eso es todo?”"}},
         {t:"La del mole — es más rara, pero solo Chelo la contesta y no siempre está",out:{r:"ok",concept:"Priorizar por alcance",why:"Dos veces por semana, pero cada falla cuesta una caminata, una interrupción y a veces una venta que se va. Es la pregunta donde el conocimiento está atrapado en la cabeza de una sola persona — que es justo para lo que sirven estas herramientas.",beat:"Chelo, desde atrás, sin levantar la vista: “Por fin. Alguien pregunta los ingredientes noventa veces al año y yo soy la única receta.”"}},
         {t:"Las dos, al mismo tiempo",out:{r:"mid",concept:"Priorizar por alcance",why:"Se puede, y una toma una tarde — pero “las dos” es cómo un proyecto de dos semanas se vuelve de dos meses. Ponlas en orden: letrero hoy, mole este mes. Medio crédito.",beat:"Perla escribe LAS DOS en el pizarrón y lo subraya dos veces. Ambición registrada."}},
         {t:"Ninguna — las preguntas de caja no valen la pena automatizar",out:{r:"bad",concept:"Priorizar por alcance",why:"Ahí adentro hay una de verdad. Descartar la caja porque la petición más ruidosa era trivial es cómo se te escapa lo único que sabe una sola persona del edificio.",beat:"Perla deja de traerte problemas. Esto es peor de lo que suena."}}]}}},
 {npc:"nando",title:"El problema de las etiquetas",start:"a",nodes:{
  a:{say:"Ya lee las facturas. Casi siempre muy bien. Pero el martes pasado leyó 12 como 112, y Chelo pidió contra un número que no existía.",
     codex:"“¿Qué tan preciso es?” es la pregunta equivocada. La correcta: ¿qué tan preciso necesita ser para que valga la pena usarlo, y qué pasa con los errores que quedan? Todo sistema tiene un presupuesto de error. O lo diseñas a propósito, o lo descubres en producción.",
     q:"¿Qué defines antes de tocar el modelo?",
     ch:[{t:"Una meta — qué precisión es suficiente, medida con facturas reales de esta tienda",next:"b"},
         {t:"Que sea lo más preciso posible, y ya",out:{r:"bad",concept:"Criterios de aceptación",why:"“Lo más preciso posible” no tiene meta, ni presupuesto, ni forma de distinguir una buena semana de una mala. Es un deseo con fecha de entrega.",beat:"Dos semanas de ajustes. Nadie puede decir si está mejor que el martes."}},
         {t:"Nada — obsérvalo un mes y ya veremos",out:{r:"mid",concept:"Criterios de aceptación",why:"Observar el uso real enseña cosas que ningún set de pruebas te dice — pero un mes de observar sin una vara contra qué medir solo te da un mes de anécdotas. Medio crédito.",beat:"Nando lleva la cuenta en una servilleta. Es, molestamente, el mejor dato que tienes."}}]},
  b:{say:"Digamos que lo dejamos en 97 de 100. Son tres facturas malas al mes, y cualquiera de ellas puede ser la del tomate.",
     codex:"Diseña la falla, no solo el acierto. La pregunta nunca es si se va a equivocar — se va a equivocar — sino: cuando falle, ¿quién se da cuenta, qué tan rápido, y cuánto cuesta? Los buenos sistemas hacen visible su propia incertidumbre en vez de esconderla tras un número seguro de sí mismo.",
     q:"¿Cómo manejas las tres?",
     ch:[{t:"Marcar las lecturas de baja confianza para que Nando las revise; el resto pasa solo",out:{r:"ok",concept:"Diseñar para la falla",why:"La máquina hace las noventa y siete y levanta la mano en las demás. La atención de Nando va exactamente donde vale algo, y un número malo se atrapa el mismo día en vez de a fin de mes.",beat:"La servilleta de Nando ahora dice: ME PREGUNTÓ 4. HIZO BIEN EN PREGUNTAR 4."}},
         {t:"Aceptar las tres — 97% está muy bien",out:{r:"bad",concept:"Diseñar para la falla",why:"97% está muy bien como titular y muy mal como plan, porque las tres no son al azar. Son las facturas desordenadas — o sea, las del proveedor con más probabilidad de quedarte corto.",beat:"Las facturas del pescadero son, estadísticamente, las tres."}},
         {t:"Que Nando las revise todas de todos modos",out:{r:"mid",concept:"Diseñar para la falla",why:"Seguro — y acabas de reconstruir sus cuarenta minutos. Si una persona lee cada renglón, la máquina no ahorró más que tecleo. Medio crédito: la cautela está bien, el objetivo no.",beat:"Nando: “O sea que las leo todas. Como antes. Pero ahora hay pantalla.”"}}]}}},
 {npc:"perla",title:"Temporada de tamales",start:"a",nodes:{
  a:{say:"Ya viene diciembre. Cada año se nos acaba la hoja de maíz y cada año Chelo dice nunca más. Alguien le dijo que la IA puede predecir cuánta vamos a necesitar.",
     codex:"Un pronóstico es un modelo entrenado con historia. Si la historia vive en un cuaderno, en la memoria de tres personas y en una hoja que empezó en marzo, no hay con qué entrenar — y una predicción segura construida sobre cuatro datos es peor que una estimación honesta, porque la gente le cree.",
     q:"Doña Chelo quiere el pronóstico de diciembre. ¿Qué le dices?",
     ch:[{t:"Construirlo — es lo de mayor valor que ha pedido",out:{r:"bad",concept:"Secuenciar",why:"Estarías pronosticando con una hoja de hace seis meses y una temporada que nadie registró. El resultado se va a ver autoritario y va a ser ficción, y ella va a pedir mercancía contra él.",beat:"El modelo predice un diciembre tranquilo. Es, por supuesto, diciembre."}},
         {t:"Todavía no — los datos de facturas empiezan a juntarse ahora, y el pronóstico se vuelve real la próxima temporada",out:{r:"ok",concept:"Secuenciar",why:"“Todavía no, y esto es lo que lo hace posible” es la frase más útil que tiene un PM. Nombra la dependencia, le arranca el reloj, y se niega a vender un número que nadie puede sostener.",beat:"Chelo, seca: “O sea que este año le calculo, como siempre.” Sí. Pero este año anotas lo que calcula."}},
         {t:"Usar el diciembre pasado del cuaderno",out:{r:"mid",concept:"Secuenciar",why:"Un año de historia a mano es real y mejor que nada — como referencia, no como pronóstico. Di “el año pasado usamos esto” y deja de hablar. Medio crédito por usar lo que existe.",beat:"El cuaderno dice ¿6 cajas? 8? — con signo de interrogación. Chelo defiende el signo de interrogación."}},
         {t:"Comprar una herramienta de pronóstico",out:{r:"bad",concept:"Secuenciar",why:"Una herramienta sin datos tiene el mismo problema que un modelo sin datos, salvo que esta se renueva cada año.",beat:"Marcus, desde otro huso horario, presiente una suscripción y se remueve."}}]}}},
 {npc:"chava",title:"Todo es chile",start:"a",nodes:{
  a:{say:"Sí, ya supe. Chelo dice que estoy rompiendo los datos. A ver — hay fila. El botón de chile está aquí mismo. El de carne está cuatro pantallas adentro. ¿Quieres que haga esperar a una abuela mientras lo busco?",
     codex:"Los datos malos casi siempre tienen detrás a una persona razonable. A alguien lo miden por velocidad, la acción correcta es lenta, y entonces toma la rápida equivocada — confiablemente, siempre. Ningún modelo, ningún script de limpieza y ningún tablero sobrevive a una fuente donde la respuesta equivocada es la fácil. Arregla las cuatro pantallas.",
     q:"Seis meses de ventas dicen que esta tienda vende casi puro chile. ¿Cuál es la jugada?",
     ch:[{t:"Limpiarlo después — una regla que reasigne los errores obvios",out:{r:"bad",concept:"Arreglar la fuente",why:"Estarías adivinando qué quiso decir Chava, para siempre, y las adivinanzas se vuelven el registro. Mientras tanto la caja sigue produciendo las mismas filas malas mañana, a la misma velocidad.",beat:"La regla funciona precioso hasta que alguien de verdad compra chile."}},
         {t:"Recapacitar a Chava — tiene que usar los botones correctos",out:{r:"mid",concept:"Arreglar la fuente",why:"Él sabe cuál es el botón correcto. Está tomando una decisión defendible bajo una restricción real: la fila. Capacitar contra un incentivo pierde contra el incentivo, siempre. Medio crédito — el estándar está bien, la palanca no.",beat:"Chava escucha, asiente, está completamente de acuerdo, y cobra el siguiente como chile."}},
         {t:"Poner en la primera pantalla las seis cosas que este mostrador de verdad vende",out:{r:"ok",concept:"Arreglar la fuente",why:"Haz que la acción correcta sea la más rápida y los datos se arreglan solos, permanentemente, sin reglas que mantener. Este es el trabajo entero: el modelo nunca fue el problema. La cuarta pantalla sí.",beat:"Chava cobra carne sin mirar el aparato. “Mmh.” Es el elogio más alto disponible."}},
         {t:"Poner a otra persona en el mostrador",out:{r:"mid",concept:"Arreglar la fuente",why:"Sí resuelve la fila — al precio de un sueldo, para no mover un botón. A veces la respuesta es más gente; aquí es una forma cara de esquivar el diseño de un menú. Medio crédito.",beat:"Marcus, a la distancia, siente aparecer una línea de nómina y no le agrada."}}]}}},
 {npc:"chelo",title:"El número del lunes",start:"a",nodes:{
  a:{say:"Ya pasó un mes. Tu cosa del teléfono contesta, ¿qué, treinta de las cuarenta? Las facturas de Nando van más rápido. Chava ya le pica al botón bueno. Así que dime derecho, mijo — ¿funcionó?",
     codex:"Las métricas del modelo contestan “¿se está portando bien?”. Las del negocio contestan “¿sirvió de algo?”. Se separan todo el tiempo: un bot puede contestar bien el 94% de las llamadas y no ahorrarle un minuto a nadie, si las que falla son justo las que necesitaban a una persona. Reporta el segundo número, y en las unidades de ella, no en las tuyas.",
     q:"¿Cómo le contestas?",
     ch:[{t:"94% de precisión, 0.8 segundos de respuesta, 31 de 40 llamadas atendidas",out:{r:"mid",concept:"Métrica de negocio vs métrica de modelo",why:"Todo cierto, todo real, y nada de eso contesta lo que ella preguntó. Ella tiene una tienda; la precisión no es algo que pueda guardar ni gastar. Medio crédito por haber medido algo.",beat:"Chelo mira los números un buen rato. “¿Y?”"}},
         {t:"Perla se levantaba de la caja cinco veces al día. Ahora una. Son como nueve horas por semana de vuelta en el piso.",next:"b"},
         {t:"Va muy bien",out:{r:"bad",concept:"Métrica de negocio vs métrica de modelo",why:"Un mes de trabajo y el reporte es una sensación. Si no puedes decir qué cambió en los términos de ella, o no lo mediste o prefieres no decirlo.",beat:"Treinta años de proveedores le han dicho a Doña Chelo que va muy bien. Tiene una cara para eso. Le estás viendo la cara."}}]},
  b:{say:"Nueve horas. Bueno. Ahora la otra — la cosa que lee las facturas del tomate. Sé honesto conmigo.",
     codex:"El entregable más difícil es el que dice deténganse. Un piloto que no rindió es información, y matarlo barato es una victoria que deberías poder decir en voz alta. La alternativa es un cementerio de proyectos a medio vivir cobrándole a alguien para siempre.",
     q:"El lector de facturas le ahorra veinte minutos por semana a Nando y te cuesta una hora por semana mantenerlo. ¿Qué va en el reporte?",
     ch:[{t:"Que cuesta más de lo que ahorra, y la recomendación es apagarlo",out:{r:"ok",concept:"Revisión honesta",why:"Señalar tu propio proyecto como el que hay que matar es lo que hace creíble cualquier otro número que reportes. Y no es un fracaso — ahora sabes exactamente qué parte sí valía la pena.",beat:"Chelo se queda callada. Luego: “Acabas de decirme que deje de pagarte por algo.” Escribe tu nombre en la pared junto a la caja."}},
         {t:"Dejarlo corriendo — ya está construido y no le hace daño a nadie",out:{r:"bad",concept:"Revisión honesta",why:"Cuesta una hora a la semana para siempre, se va a desviar, y un día va a estar mal mientras nadie mira. “Ya está construido” es la razón más cara que existe para conservar algo.",beat:"Once meses después el pescadero cambia su letra. Nadie se da cuenta en seis semanas."}},
         {t:"Reportar los veinte minutos ahorrados y omitir el costo de mantenimiento",out:{r:"bad",concept:"Revisión honesta",why:"Eso no es un reporte, es un argumento de venta con una hoja de cálculo encima. La primera vez que ella encuentre la hora faltante, todos los números que le diste valen cero.",beat:"Nando sabe. Nando siempre sabe."}},
         {t:"Pasárselo a Nando para que él lo mantenga",out:{r:"mid",concept:"Revisión honesta",why:"A veces es exactamente lo correcto — quien está más cerca del trabajo debería ser dueño de la herramienta. Pero pasarle una hora semanal de mantenimiento a alguien que no la pidió es una transferencia de costo disfrazada de entrega. Medio crédito: pregúntale primero.",beat:"Nando, sin alterarse: “¿Es aquí donde se vuelve mi problema?”"}}]}}}
];
